import numpy as np

class OnlineNormalizer:
    def __init__(self, feature_dim, alpha=0.01):
        self.n = 0
        self.mean = np.zeros(feature_dim)
        self.M2 = np.zeros(feature_dim)
        self.alpha = alpha  # Forgetting factor

    def update(self, x):
        self.n += 1
        delta = x - self.mean
        self.mean += delta / self.n
        delta2 = x - self.mean
        self.M2 += delta * delta2

        # Exponential forgetting for non-stationary data
        if self.alpha > 0 and self.n > 100:
            self.M2 *= (1 - self.alpha)

    def transform(self, x):
        variance = self.M2 / self.n if self.n > 1 else 1
        std = np.sqrt(variance) + 1e-8
        return (x - self.mean) / std

    def get_stats(self):
        return self.mean, self.M2 / max(self.n, 1)

import torch
import torch.nn as nn
import torch.nn.functional as F

class FocalLoss(nn.Module):
    def __init__(self, alpha=None, gamma=2, reduction='mean'):
        super().__init__()
        self.alpha = alpha
        self.gamma = gamma
        self.reduction = reduction

    def forward(self, inputs, targets):
        ce_loss = F.cross_entropy(inputs, targets, reduction='none', weight=self.alpha)
        pt = torch.exp(-ce_loss)
        focal_loss = ((1 - pt) ** self.gamma) * ce_loss

        if self.reduction == 'mean':
            return focal_loss.mean()
        elif self.reduction == 'sum':
            return focal_loss.sum()
        else:
            return focal_loss
